describe('process', () => {
    let ApprovalURL = 'https://example.proton.me';
    let ReturnHost = 'https://return.proton.me';
    let Token = 'some-payment-token-222';
    let api: jest.Mock;
    let signal: AbortSignal;

    beforeEach(() => {
        api = jest.fn();
        signal = {
            aborted: false,
            reason: null,
            onabort: jest.fn(),
            throwIfAborted: jest.fn(),
            addEventListener: jest.fn(),
            removeEventListener: jest.fn(),
            dispatchEvent: jest.fn(),
        };
    });

    it('should open the ApprovalURL', () => {
        tab.closed = true; // prevents the test from hanging because of an unhandled promise
        process({ api, ApprovalURL, ReturnHost, signal, Token }).catch(() => {});

        expect(window.open).toHaveBeenCalledWith(ApprovalURL);
    });

    it('should add abort listener to the signal', async () => {
        const promise = process({ api, ApprovalURL, ReturnHost, signal, Token });

        expect(signal.addEventListener).toHaveBeenCalledTimes(1);
        const signalAddEventListenerMock = signal.addEventListener as jest.Mock;
        expect(signalAddEventListenerMock.mock.lastCall[0]).toEqual('abort');
        expect(typeof signalAddEventListenerMock.mock.lastCall[1]).toBe('function');

        expect(window.addEventListener).toHaveBeenCalledTimes(1);
        const windowAddEventListenerMock = window.addEventListener as jest.Mock;
        expect(windowAddEventListenerMock.mock.lastCall[0]).toEqual('message');
        expect(typeof windowAddEventListenerMock.mock.lastCall[1]).toEqual('function');
        const onMessage = windowAddEventListenerMock.mock.lastCall[1];

        const abort = signalAddEventListenerMock.mock.lastCall[1];

        abort();

        expect(window.removeEventListener).toHaveBeenCalledWith('message', onMessage, false);
        expect(signal.removeEventListener).toHaveBeenCalledWith('abort', abort);
        expect(tab.close).toHaveBeenCalled();
        await expect(promise).rejects.toEqual(new Error(c('Error').t`Process aborted`));
    });

    it('should resolve if Status is STATUS_CHARGEABLE', async () => {
        tab.closed = true;
        api.mockResolvedValue({
            Status: PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE,
        });

        const promise = process({ api, ApprovalURL, ReturnHost, signal, Token });

        await expect(promise).resolves.toEqual(undefined);
    });

    it.each([
        PAYMENT_TOKEN_STATUS.STATUS_PENDING,
        PAYMENT_TOKEN_STATUS.STATUS_FAILED,
        PAYMENT_TOKEN_STATUS.STATUS_CONSUMED,
        PAYMENT_TOKEN_STATUS.STATUS_NOT_SUPPORTED,
    ])('should reject if Status is %s', async (Status) => {
        tab.closed = true;
        api.mockResolvedValue({
            Status,
        });

        const promise = process({ api, ApprovalURL, ReturnHost, signal, Token });

        await expect(promise).rejects.toEqual({ tryAgain: true });
    });

    it('should re-try to confirm until the tab is closed', async () => {
        api.mockResolvedValue({
            Status: PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE,
        });

        const delayListening = 10;
        const promise = process({ api, ApprovalURL, ReturnHost, signal, Token }, delayListening);
        await delay(delayListening * 5);

        tab.closed = true;

        await expect(promise).resolves.toEqual(undefined);
    });
});
import { PAYMENT_METHOD_TYPES, PAYMENT_TOKEN_STATUS } from '@proton/shared/lib/constants';
import { Currency } from '@proton/shared/lib/interfaces';

export interface CardPayment {
    Type: PAYMENT_METHOD_TYPES.CARD;
    Details: {
        Name: string;
        Number: string;
        ExpMonth: string;
        ExpYear: string;
        CVC: string;
        ZIP: string;
        Country: string;
    };
}

export function isCardPayment(payment: any): payment is CardPayment {
    return payment?.Type === PAYMENT_METHOD_TYPES.CARD && !!payment?.Details;
}

export interface TokenPayment {
    Type: PAYMENT_METHOD_TYPES.TOKEN;
    Details: {
        Token: string;
    };
}

export function isTokenPayment(payment: any): payment is TokenPayment {
    return payment?.Type === PAYMENT_METHOD_TYPES.TOKEN || !!(payment as any)?.Details?.Token;
}

export interface PaypalPayment {
    Type: PAYMENT_METHOD_TYPES.PAYPAL | PAYMENT_METHOD_TYPES.PAYPAL_CREDIT;
}

export interface WrappedPaypalPayment {
    Payment: PaypalPayment;
}

export function isPaypalPayment(payment: any): payment is PaypalPayment {
    return (
        payment && (payment.Type === PAYMENT_METHOD_TYPES.PAYPAL || payment.Type === PAYMENT_METHOD_TYPES.PAYPAL_CREDIT)
    );
}

export interface ExistingPayment {
    PaymentMethodID: string;
}

export function isExistingPayment(data: any): data is ExistingPayment {
    return !!data && typeof data.PaymentMethodID === 'string';
}

export interface WrappedCardPayment {
    Payment: CardPayment;
}

export interface TokenPaymentMethod {
    Payment: TokenPayment;
}

export function isTokenPaymentMethod(data: any): data is TokenPaymentMethod {
    return !!data && isTokenPayment(data.Payment);
}

export interface AmountAndCurrency {
    Amount: number;
    Currency: Currency;
}

export interface CardModel {
    fullname: string;
    number: string;
    month: string;
    year: string;
    cvc: string;
    zip: string;
    country: string;
}

export interface PaymentTokenResult {
    Token: string;
    Status: PAYMENT_TOKEN_STATUS;
    ApprovalURL?: string;
    ReturnHost?: string;
}

import { useState } from 'react';

import { c } from 'ttag';

import { Button, Href } from '@proton/atoms';
import { buyCredit } from '@proton/shared/lib/api/payments';
import {
    APPS,
    DEFAULT_CREDITS_AMOUNT,
    DEFAULT_CURRENCY,
    MIN_CREDIT_AMOUNT,
    PAYMENT_METHOD_TYPES,
} from '@proton/shared/lib/constants';
import { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';
import { Currency } from '@proton/shared/lib/interfaces';

import {
    Form,
    ModalProps,
    ModalTwo,
    ModalTwoContent,
    ModalTwoFooter,
    ModalTwoHeader,
    PrimaryButton,
    useDebounceInput,
} from '../../components';
import { useApi, useConfig, useEventManager, useLoading, useModals, useNotifications } from '../../hooks';
import AmountRow from './AmountRow';
import Payment from './Payment';
import PaymentInfo from './PaymentInfo';
import StyledPayPalButton from './StyledPayPalButton';
import { AmountAndCurrency, ExistingPayment, TokenPaymentMethod, WrappedCardPayment } from './interface';
import { createPaymentToken } from './paymentTokenHelper';
import usePayment from './usePayment';

const getCurrenciesI18N = () => ({
    EUR: c('Monetary unit').t`Euro`,
    CHF: c('Monetary unit').t`Swiss franc`,
    USD: c('Monetary unit').t`Dollar`,
});

const CreditsModal = (props: ModalProps) => {
    const api = useApi();
    const { APP_NAME } = useConfig();
    const { call } = useEventManager();
    const { createModal } = useModals();
    const { createNotification } = useNotifications();
    const [loading, withLoading] = useLoading();
    const [currency, setCurrency] = useState<Currency>(DEFAULT_CURRENCY);
    const [amount, setAmount] = useState(DEFAULT_CREDITS_AMOUNT);
    const debouncedAmount = useDebounceInput(amount);
    const i18n = getCurrenciesI18N();
    const i18nCurrency = i18n[currency];

    const handleSubmit = async (params: TokenPaymentMethod | WrappedCardPayment | ExistingPayment) => {
        const amountAndCurrency: AmountAndCurrency = { Amount: debouncedAmount, Currency: currency };
        const tokenPaymentMethod = await createPaymentToken(
            {
                params,
                api,
                createModal,
            },
            amountAndCurrency
        );

        await api(buyCredit({ ...tokenPaymentMethod, ...amountAndCurrency }));
        await call();
        props.onClose?.();
        createNotification({ text: c('Success').t`Credits added` });
    };

    const { card, setCard, cardErrors, handleCardSubmit, method, setMethod, parameters, canPay, paypal, paypalCredit } =
        usePayment({
            amount: debouncedAmount,
            currency,
            onPaypalPay: handleSubmit,
        });

    const submit =
        debouncedAmount >= MIN_CREDIT_AMOUNT ? (
            method === PAYMENT_METHOD_TYPES.PAYPAL ? (
                <StyledPayPalButton paypal={paypal} amount={debouncedAmount} data-testid="paypal-button" />
            ) : (
                <PrimaryButton loading={loading} disabled={!canPay} type="submit" data-testid="top-up-button">{c(
                    'Action'
                ).t`Top up`}</PrimaryButton>
            )
        ) : null;

    return (
        <ModalTwo
            className="credits-modal"
            size="large"
            as={Form}
            onSubmit={() => {
                if (!handleCardSubmit() || !parameters) {
                    return;
                }

                withLoading(handleSubmit(parameters));
            }}
            {...props}
        >
            <ModalTwoHeader title={c('Title').t`Add credits`} />
            <ModalTwoContent>
                <PaymentInfo method={method} />
                <div className="mb-4">
                    <div>
                        {c('Info')
                            .jt`Top up your account with credits that you can use to subscribe to a new plan or renew your current plan. You get one credit for every ${i18nCurrency} spent.`}
                    </div>
                    <Href
                        href={
                            APP_NAME === APPS.PROTONVPN_SETTINGS
                                ? 'https://protonvpn.com/support/vpn-credit-proration/'
                                : getKnowledgeBaseUrl('/credit-proration-coupons')
                        }
                    >
                        {c('Link').t`Learn more`}
                    </Href>
